"use client";
import { useCallback, useEffect, useState } from "react";
import type { Plan, PlanCell } from "./types";

/** LOCAL PLANNER EDITS.
 *
 *  plan.json is generated by the pipeline and is the baseline. Anything the
 *  planner types lives here, in localStorage, layered ON TOP of that baseline
 *  rather than replacing it — so a rebuild of the data never silently wipes
 *  someone's week, and "reset" always has something true to go back to.
 *
 *  There is no backend in this demo. That is a real limitation and the UI says
 *  so rather than implying the edits are shared with anyone. */

const CELL_KEY = "planner:cells";
const PART_KEY = "planner:parts";

export interface CellEdit { part?: string; qty?: number }
export interface CustomPart {
  part: string; process: string; die: string;
  achieved_spm: number; kwh_per_1000: number;
  /** anything the user typed is their own estimate until a run proves it */
  spm_trust: "user";
}

const cellId = (date: string, shift: string) => `${date}|${shift}`;

function read<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : fallback;
  } catch { return fallback; }          // private mode, blocked storage, bad JSON
}
function write(key: string, v: unknown) {
  try { localStorage.setItem(key, JSON.stringify(v)); } catch { /* non-fatal */ }
}

export interface PartRow {
  part: string; process: string; die: string;
  achieved_spm: number; kwh_per_1000: number;
  spm_trust: string;
}

export function usePlanner(plan: Plan | null) {
  const [edits, setEdits] = useState<Record<string, CellEdit>>({});
  const [custom, setCustom] = useState<CustomPart[]>([]);
  const [ready, setReady] = useState(false);

  // read AFTER mount: localStorage does not exist during the server render and
  // reading it in useState's initialiser is a hydration mismatch waiting
  useEffect(() => {
    setEdits(read(CELL_KEY, {}));
    setCustom(read(PART_KEY, []));
    setReady(true);
  }, []);

  const parts: PartRow[] = [
    ...(plan?.parts ?? []).map((p) => ({ ...p, spm_trust: (p as PartRow).spm_trust ?? "estimated" })),
    ...custom,
  ];

  const partOf = useCallback((id: string) => parts.find((p) => p.part === id), [parts]);

  /** The baseline cell with any local edit applied, and every derived number
   *  RECOMPUTED — editing a quantity has to move feasibility, overtime and the
   *  realistic quantity with it, or the capacity check becomes decoration. */
  const resolve = useCallback((c: PlanCell): PlanCell => {
    const e = edits[cellId(c.date, c.shift)];
    if (!e) return c;
    const part = e.part ?? c.part;
    const qty = e.qty ?? c.qty;
    const p = partOf(part);
    const achieved = p?.achieved_spm ?? c.achieved_spm;
    // the shift's available minutes, backed out of the baseline so a changed
    // part keeps whatever changeover allowance the generator gave this cell
    const avail = Math.max(1, Math.round(c.qty / Math.max(0.01, c.required_spm)));
    const required = +(qty / avail).toFixed(2);
    const feasible = required <= achieved;
    return {
      ...c, part, qty,
      process: p?.process ?? c.process,
      die: p?.die ?? c.die,
      required_spm: required,
      achieved_spm: achieved,
      spm_trust: p?.spm_trust ?? c.spm_trust,
      feasible,
      shortfall_pct: required ? Math.max(0, +(100 * (required - achieved) / required).toFixed(1)) : 0,
      overtime_min: feasible ? 0 : Math.round(qty / achieved - avail),
      realistic_qty: feasible ? qty : Math.round(achieved * avail),
      energy_kwh: +(qty / 1000 * (p?.kwh_per_1000 ?? 0)).toFixed(1),
      edited: true,
    } as PlanCell & { edited: boolean };
  }, [edits, partOf]);

  const setCell = useCallback((date: string, shift: string, e: CellEdit) => {
    setEdits((prev) => {
      const next = { ...prev, [cellId(date, shift)]: { ...prev[cellId(date, shift)], ...e } };
      write(CELL_KEY, next);
      return next;
    });
  }, []);

  const clearCell = useCallback((date: string, shift: string) => {
    setEdits((prev) => {
      const next = { ...prev };
      delete next[cellId(date, shift)];
      write(CELL_KEY, next);
      return next;
    });
  }, []);

  const addPart = useCallback((p: CustomPart) => {
    setCustom((prev) => {
      const next = [...prev.filter((x) => x.part !== p.part), p];
      write(PART_KEY, next);
      return next;
    });
  }, []);

  const removePart = useCallback((id: string) => {
    setCustom((prev) => {
      const next = prev.filter((x) => x.part !== id);
      write(PART_KEY, next);
      return next;
    });
  }, []);

  const resetAll = useCallback(() => {
    setEdits({}); setCustom([]);
    write(CELL_KEY, {}); write(PART_KEY, []);
  }, []);

  return { ready, parts, custom, resolve, setCell, clearCell, addPart, removePart,
           resetAll, editCount: Object.keys(edits).length };
}
